// PID line follower: 5 IR sensors (A0..A4) + 2 DC motors via an H-bridge.
// Sensors read HIGH/analog over a dark line on light floor (flip LINE_IS_DARK if reversed).

// --- motor pins (H-bridge: 2 dir + 1 PWM per motor) ---
const int L_IN1=7, L_IN2=8, L_PWM=9;
const int R_IN1=4, R_IN2=5, R_PWM=6;

// --- sensor pins ---
const int SENS[5] = {A0, A1, A2, A3, A4};
const int WEIGHT[5] = {-2, -1, 0, 1, 2};   // position weighting
const bool LINE_IS_DARK = true;
const int THRESHOLD = 500;                  // analog threshold

// --- tuning ---
float Kp = 60, Ki = 0, Kd = 400;
int BASE = 120;                             // base speed 0..255
float integ = 0, prevErr = 0;
unsigned long last = 0;

void motor(int in1, int in2, int pwm, int speed){
  bool fwd = speed >= 0; int p = constrain(abs(speed), 0, 255);
  digitalWrite(in1, fwd); digitalWrite(in2, !fwd); analogWrite(pwm, p);
}

// returns line position error (-2..+2), or 999 if line lost
float readError(){
  long sum = 0, active = 0;
  for (int i = 0; i < 5; i++){
    int v = analogRead(SENS[i]);
    bool on = LINE_IS_DARK ? (v > THRESHOLD) : (v < THRESHOLD);
    if (on){ sum += WEIGHT[i]; active++; }
  }
  if (active == 0) return 999;              // lost the line
  return (float)sum / active;
}

void setup(){
  int mp[] = {L_IN1,L_IN2,L_PWM,R_IN1,R_IN2,R_PWM};
  for (int i=0;i<6;i++) pinMode(mp[i], OUTPUT);
  Serial.begin(115200);
}

void loop(){
  if (millis() - last < 5) return;          // ~200 Hz
  float dt = (millis() - last) / 1000.0; last = millis();

  float err = readError();
  if (err == 999){                          // line lost: spin toward last seen side
    int dir = prevErr >= 0 ? 1 : -1;
    motor(L_IN1,L_IN2,L_PWM,  dir*BASE);
    motor(R_IN1,R_IN2,R_PWM, -dir*BASE);
    return;
  }
  integ += err * dt; integ = constrain(integ, -50, 50);
  float deriv = (err - prevErr) / dt; prevErr = err;
  float steer = Kp*err + Ki*integ + Kd*deriv;

  motor(L_IN1,L_IN2,L_PWM, constrain(BASE + steer, -255, 255));
  motor(R_IN1,R_IN2,R_PWM, constrain(BASE - steer, -255, 255));
}
